require_once __DIR__.'/../includes/core/session.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../classes/identity/OfficePolicy.php';require_once __DIR__.'/../classes/system/SystemLogger.php';
header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');
try{if(empty($_SESSION['user_id'])){http_response_code(401);throw new RuntimeException();}$db=(new Database)->getConnection();$actor=OfficePolicy::actor($db,(int)$_SESSION['user_id']);if($actor['role']!=='super_admin'){http_response_code(403);throw new RuntimeException();}$name=$_GET['file']??null;if(!is_string($name)||!preg_match('/^backup_[0-9_-]+\.sql$/D',$name))throw new RuntimeException();$root=realpath(__DIR__.'/../storage/backups');$file=$root?realpath($root.'/'.$name):false;if(!$root||!$file||!str_starts_with(strtolower($file),strtolower($root.DIRECTORY_SEPARATOR))||!is_file($file))throw new RuntimeException();(new SystemLogger($db))->adminAction('Downloaded a database backup',$actor['id'],['action'=>'download_backup']);header('Content-Type: application/sql');header('Content-Disposition: attachment; filename="'.$name.'"');header('Content-Length: '.filesize($file));readfile($file);}catch(Throwable $e){if(http_response_code()<400)http_response_code(404);}
